<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Autorização · Requisição #{{ $fuelRequest->request_number }}</title><style>@page{size:A4 portrait;margin:8mm}*{box-sizing:border-box}body{margin:0;color:#111;font-family:Arial,Helvetica,sans-serif;font-size:8.5px}.sheet{width:100%}.copy{height:87mm;border:1px solid #111;padding:4mm 5mm;page-break-inside:avoid;overflow:hidden}.copy+.copy{margin-top:3mm;border-top:2px dashed #111}.brand{display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:2px solid #111;padding-bottom:3mm}.brand img{width:34mm;height:auto}.brand h1{margin:0;font-size:14px}.brand p{margin:3px 0 0;font-size:8px}.via{font-size:11px;font-weight:800;text-transform:uppercase}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px 9px;margin:4mm 0}.field{border-bottom:1px solid #b7b7b7;padding:2px 0}.field span{display:block;color:#555;font-size:6.5px;font-weight:700;text-transform:uppercase}.field strong{display:block;margin-top:2px;font-size:8.5px}.auth{display:grid;grid-template-columns:1.15fr .85fr;gap:8px;border:1px solid #111;margin-top:3mm}.auth-main{padding:3mm}.auth-main h2{margin:0;font-size:10px;text-transform:uppercase}.auth-main p{margin:4px 0 0;font-size:8px}.valid{padding:3mm;border-left:1px solid #111;text-align:center}.valid span{display:block;font-size:7px;font-weight:700}.valid strong{display:block;margin-top:5px;font-size:13px}.signatures{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22mm;margin-top:7mm}.signature{border-top:1px solid #111;padding-top:4px;text-align:center;font-size:7px}.footer{margin-top:3mm;text-align:center;font-size:6.5px;color:#555}@media screen{body{padding:10mm;background:#697076}.sheet{max-width:194mm;margin:0 auto;background:#fff;box-shadow:0 0 8px rgba(0,0,0,.35)}}@media print{body{background:#fff}}</style></head><body><main class="sheet">@php($copies=[['VIA POSTO','Posto autorizado'],['VIA MOTORISTA','Motorista responsável'],['VIA CMRP','Arquivo CMRP']])@foreach($copies as [$via,$destino])<section class="copy"><header class="brand"><img src="{{ asset('images/camara-municipal-ribeirao-preto-logo.png') }}" alt="Câmara Municipal de Ribeirão Preto"><div><h1>Requisição de Combustível · #{{ $fuelRequest->request_number }}</h1><p>Autorização interna de abastecimento · {{ $destino }}</p></div><strong class="via">{{ $via }}</strong></header><div class="grid"><div class="field"><span>Solicitante</span><strong>{{ $fuelRequest->requester?->full_name ?? '—' }}</strong></div><div class="field"><span>Veículo</span><strong>{{ $fuelRequest->vehicle?->model ?? '—' }}</strong></div><div class="field"><span>Placa</span><strong>{{ $fuelRequest->vehicle?->plate ?? '—' }}</strong></div><div class="field"><span>Motorista</span><strong>{{ $fuelRequest->driver?->full_name ?? '—' }}</strong></div><div class="field"><span>Combustível</span><strong>{{ $fuelRequest->fuelType?->name ?? '—' }}</strong></div><div class="field"><span>Hodômetro</span><strong>{{ number_format($fuelRequest->odometer,0,',','.') }} km</strong></div></div><section class="auth"><div class="auth-main"><h2>Autorização de abastecimento</h2>@if($fuelRequest->authorization_at)<p>Autorizada em <strong>{{ $fuelRequest->authorization_at->format('d/m/Y H:i') }}</strong> por <strong>{{ $fuelRequest->approver?->name ?? 'Registro histórico importado' }}</strong>.</p>@else<p><strong>Aguardando autorização do operador.</strong> Este documento não autoriza abastecimento enquanto a requisição não estiver aprovada.</p>@endif</div><div class="valid"><span>VALIDADE</span>@if($fuelRequest->authorization_expires_at)<strong>VÁLIDO POR 3 DIAS</strong><span>até {{ $fuelRequest->authorization_expires_at->format('d/m/Y H:i') }}</span>@else<strong>AGUARDANDO</strong><span>autorização</span>@endif</div></section><div class="signatures"><div class="signature">Motorista / solicitante</div><div class="signature">Responsável administrativo / operador</div></div><div class="footer">Câmara Municipal de Ribeirão Preto · Frota Câmara · Documento interno · Emitido em {{ now()->format('d/m/Y H:i') }} · {{ $via }}</div></section>@endforeach</main><script>window.addEventListener('load',()=>window.print())</script></body></html>
